// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(amount > 0);

        vm.deal(sender, amount);

        uint oldCount = c.depositsCount();

        vm.prank(sender);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        assertTrue(ok);

        assertTrue(c.depositsCount() == oldCount + 1);
    }
}
